/**
 * Fast Local Alpine.js Micro-Runtime
 * 100% Offline, Zero-Lag, Instant Initialization
 */
(function(global) {
    class MicroAlpine {
        constructor() {
            this.stores = {};
            this.components = [];
        }

        data(name, callback) {
            this.stores[name] = callback;
        }

        start() {
            if (document.readyState === 'loading') {
                document.addEventListener('DOMContentLoaded', () => this.initTree(document.body));
            } else {
                this.initTree(document.body);
            }
        }

        initTree(root) {
            const elements = root.querySelectorAll ? Array.from(root.querySelectorAll('[x-data]')) : [];
            if (root.hasAttribute && root.hasAttribute('x-data')) {
                elements.unshift(root);
            }

            elements.forEach(el => {
                if (!el._x_dataStack) {
                    this.initComponent(el);
                }
            });
        }

        initComponent(el) {
            const dataExpr = el.getAttribute('x-data');
            let scope = {};

            try {
                if (dataExpr) {
                    const fn = new Function('Alpine', `with(this) { return (${dataExpr}); }`);
                    scope = fn.call(window, this) || {};
                }
            } catch (e) {
                console.warn('MicroAlpine x-data parse warning:', e);
            }

            // Create reactive proxy
            const self = this;
            const reactiveScope = this.reactive(scope, () => {
                self.updateComponent(el);
            });

            reactiveScope.$nextTick = function(cb) {
                setTimeout(cb, 16);
            };

            el._x_dataStack = reactiveScope;

            // Run init hook if provided
            if (typeof reactiveScope.init === 'function') {
                reactiveScope.init();
            }

            this.bindDirectives(el, reactiveScope);
            this.updateComponent(el);
        }

        reactive(obj, onChange) {
            const self = this;
            if (!obj || typeof obj !== 'object') return obj;

            return new Proxy(obj, {
                get(target, prop) {
                    const val = target[prop];
                    if (typeof val === 'function') {
                        return val.bind(target);
                    }
                    if (val && typeof val === 'object') {
                        return self.reactive(val, onChange);
                    }
                    return val;
                },
                set(target, prop, value) {
                    target[prop] = value;
                    onChange();
                    return true;
                }
            });
        }

        bindDirectives(rootEl, scope) {
            const walker = document.createTreeWalker(rootEl, NodeFilter.SHOW_ELEMENT, null, false);
            let node = walker.currentNode;

            while (node) {
                this.bindNodeDirectives(node, scope, rootEl);
                node = walker.nextNode();
            }
        }

        bindNodeDirectives(el, scope, rootEl) {
            if (el !== rootEl && el.hasAttribute('x-data')) return;

            Array.from(el.attributes).forEach(attr => {
                const name = attr.name;
                const expr = attr.value;

                // Event listener: @click, @change, x-on:click
                if (name.startsWith('@') || name.startsWith('x-on:')) {
                    const eventName = name.startsWith('@') ? name.substring(1) : name.substring(5);
                    el.addEventListener(eventName, (e) => {
                        try {
                            const fn = new Function('$event', `with(this) { ${expr}; }`);
                            fn.call(scope, e);
                        } catch (err) {
                            console.error('MicroAlpine event error:', err);
                        }
                    });
                }

                // Two-way binding: x-model / x-model.number
                if (name.startsWith('x-model')) {
                    const isNumber = name.includes('.number');
                    const prop = expr;

                    el.addEventListener('input', (e) => {
                        const val = isNumber ? parseFloat(e.target.value) || 0 : e.target.value;
                        this.setPath(scope, prop, val);
                    });

                    el.addEventListener('change', (e) => {
                        const val = isNumber ? parseFloat(e.target.value) || 0 : e.target.value;
                        this.setPath(scope, prop, val);
                    });
                }
            });
        }

        updateComponent(rootEl) {
            const scope = rootEl._x_dataStack;
            if (!scope) return;

            const walker = document.createTreeWalker(rootEl, NodeFilter.SHOW_ELEMENT, null, false);
            let el = walker.currentNode;

            while (el) {
                if (el !== rootEl && el.hasAttribute('x-data')) {
                    el = walker.nextNode();
                    continue;
                }

                // x-show
                if (el.hasAttribute('x-show')) {
                    const expr = el.getAttribute('x-show');
                    try {
                        const show = this.evaluate(expr, scope);
                        el.style.display = show ? '' : 'none';
                    } catch (e) {}
                }

                // x-text
                if (el.hasAttribute('x-text')) {
                    const expr = el.getAttribute('x-text');
                    try {
                        const text = this.evaluate(expr, scope);
                        el.textContent = text !== undefined ? text : '';
                    } catch (e) {}
                }

                // x-bind:value / :value / :disabled / :max
                Array.from(el.attributes).forEach(attr => {
                    if (attr.name.startsWith(':') || attr.name.startsWith('x-bind:')) {
                        const propName = attr.name.startsWith(':') ? attr.name.substring(1) : attr.name.substring(7);
                        try {
                            const val = this.evaluate(attr.value, scope);
                            if (propName === 'disabled') {
                                el.disabled = Boolean(val);
                            } else if (propName === 'max') {
                                el.max = val;
                            } else if (propName === 'class' && typeof val === 'string') {
                                el.className = val;
                            } else {
                                el.setAttribute(propName, val);
                            }
                        } catch (e) {}
                    }
                });

                // sync x-model value to input
                if (el.hasAttribute('x-model') || el.hasAttribute('x-model.number')) {
                    const prop = el.getAttribute('x-model') || el.getAttribute('x-model.number');
                    try {
                        const val = this.getPath(scope, prop);
                        if (val !== undefined && el.value !== String(val)) {
                            el.value = val;
                        }
                    } catch (e) {}
                }

                el = walker.nextNode();
            }
        }

        evaluate(expr, scope) {
            const fn = new Function(`with(this) { return (${expr}); }`);
            return fn.call(scope);
        }

        getPath(obj, path) {
            return path.split('.').reduce((o, i) => (o ? o[i] : undefined), obj);
        }

        setPath(obj, path, value) {
            const parts = path.split('.');
            let curr = obj;
            for (let i = 0; i < parts.length - 1; i++) {
                if (!curr[parts[i]]) curr[parts[i]] = {};
                curr = curr[parts[i]];
            }
            curr[parts[parts.length - 1]] = value;
        }
    }

    const instance = new MicroAlpine();
    global.Alpine = instance;
    instance.start();
})(window);
